const state={tab:'talk',profile:JSON.parse(localStorage.getItem('udaan_profile')||'{}'),transcript:'सुबह मैं घर पर गायों का दूध निकालता हूँ। फिर पिताजी की दुकान पर ग्राहकों को सामान देता हूँ। कभी-कभी मोबाइल की छोटी-मोटी खराबी भी ठीक कर देता हूँ।',skills:[],selectedCareer:localStorage.getItem('udaan_career')||'mobile',saved:JSON.parse(localStorage.getItem('udaan_saved')||'[]'),done:JSON.parse(localStorage.getItem('udaan_done')||'[]'),selectedOpportunity:'op1',opFilter:'सभी',mapList:false,recording:false,teacherInput:'बच्चों को पौधों की देखभाल सिखानी है। पहले बीज के बारे में बताओ, फिर मिट्टी, पानी, धूप और खाद समझाओ।',module:null,pricing:'Free',familyCareer:localStorage.getItem('udaan_career')||'mobile',familySummary:null,consent:false};
function persist(){localStorage.setItem('udaan_profile',JSON.stringify(state.profile));localStorage.setItem('udaan_saved',JSON.stringify(state.saved));localStorage.setItem('udaan_done',JSON.stringify(state.done));localStorage.setItem('udaan_career',state.selectedCareer)}function toast(msg){$('#toastRoot').innerHTML=`<div class="toast" role="status">${esc(msg)}</div>`;setTimeout(()=>$('#toastRoot').innerHTML='',2600)}function speak(text){if(!('speechSynthesis'in window)){toast('इस डिवाइस पर ऑडियो सुविधा उपलब्ध नहीं है।');return}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang=(localStorage.getItem('udaan_language')||'hi')==='en'?'en-IN':'hi-IN';speechSynthesis.speak(u)}function career(id){return careers.find(c=>c.id===id)||careers[0]}function careerScore(c){const t=(state.transcript+' '+(state.profile.interests||'')).toLowerCase();let n=0;c.skills.forEach(k=>{if(t.includes(k.toLowerCase()))n+=1});if(state.skills.some(s=>c.skills.some(k=>s.label.toLowerCase().includes(k.toLowerCase())||k.toLowerCase().includes(s.label.toLowerCase()))))n+=2;return n}function recommended(){return [...careers].sort((a,b)=>careerScore(b)-careerScore(a))}function skillExtract(text){const rules=[['पशु देखभाल','आपने पशुओं की देखभाल का ज़िक्र किया।','पशु, गाय, दूध, बकरी, animal, cow, dairy'],['ग्राहक से बातचीत','लोगों की मदद और ग्राहकों से बात करने का अनुभव।','ग्राहक, दुकान, सामान, बातचीत, customer, shop, sell'],['बुनियादी मरम्मत','छोटी खराबियाँ ठीक करने की शुरुआती समझ।','मरम्मत, ठीक, खराबी, मोबाइल, repair, mobile'],['जिम्मेदारी और समय प्रबंधन','रोज़ के काम संभालने से जिम्मेदारी का अनुभव दिखता है।','रोज़, सुबह, जिम्मेदारी, समय, काम'],['रचनात्मक हाथ का काम','बनाने, सिलाई या डिज़ाइन में रुचि हो सकती है।','सिलाई, कपड़ा, डिज़ाइन, craft, stitch'],['खेती और प्रकृति','पौधों, खेत या कृषि कार्य का अनुभव।','खेती, खेत, पौधा, मिट्टी, फसल, farm, plant']];const lower=text.toLowerCase();return rules.filter(r=>r[2].split(', ').some(k=>lower.includes(k.toLowerCase()))).map(r=>({label:r[0],why:r[1],confirmed:false})).slice(0,6)}function setTab(tab){state.tab=tab;document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));render()}function header(title,sub,action=''){return `<div class="section-head"><div><h2>${title}</h2><p>${sub}</p></div>${action}</div>`}
