function opportunityCard(o,compact=false){return `<div class="card ${compact?'':'map-details'}"><div class="row between"><span class="tag">${o.emoji} ${esc(o.type)}</span><span class="tag tag-yellow">${esc(o.status)}</span></div><h3 style="margin-top:12px">${esc(o.name)}</h3><p>${esc(o.detail)}</p><div class="row between"><span class="small-label">📍 डेमो दूरी: ${o.distance} किमी</span><button class="btn btn-outline btn-small" data-action="select-op" data-id="${o.id}">विवरण देखें</button></div>${!compact&&state.selectedOpportunity===o.id?`<div class="divider"></div><p><strong>क्या सीख सकते हैं:</strong> ${esc(o.detail)}</p><p><strong>पात्रता:</strong> ${esc(o.eligibility)}</p><p class="source">स्रोत: ${esc(o.source)}</p><div class="row" style="flex-wrap:wrap"><button class="btn btn-primary btn-small" data-action="save-op" data-id="${o.id}">${state.saved.includes(o.id)?'सेव है ✓':'मौका सेव करें'}</button><button class="btn btn-outline btn-small" data-action="route-op" data-id="${o.id}">रास्ता देखें</button></div>`:''}</div>`}
function renderChances(){const filtered=opportunities.filter(o=>state.opFilter==='सभी'||o.type===state.opFilter||o.career===state.selectedCareer);const selected=opportunities.find(o=>o.id===state.selectedOpportunity)||opportunities[0];return `<section class="welcome"><div><div class="eyebrow">आपके आसपास की संभावनाएँ</div><h1>मौके खोजें।<br>सवाल पूछें। आगे बढ़ें।</h1><p>नक्शे पर प्रशिक्षण और सीखने के उदाहरण देखें। वास्तविक अवसर, दूरी और उपलब्धता हमेशा स्रोत से जाँचें।</p><button class="btn btn-primary" data-action="show-list">${state.mapList?'नक्शा देखें':'सूची में देखें'}</button></div><div class="hero-art" aria-hidden="true"><span>🧭</span></div></section>
${header('आपके आस-पास के मौके','नक्शा सबसे पहले — सभी पिन नमूना डेटा हैं।')}<div class="card"><div class="row between"><h3>📍 गाँव का अवसर नक्शा</h3><button class="btn btn-outline btn-small" data-action="show-list">${state.mapList?'नक्शा':'सूची'}</button></div><div class="filter-row"><select id="opFilter" aria-label="मौके का प्रकार">${['सभी','प्रशिक्षण','मार्गदर्शन','कौशल प्रशिक्षण','स्थानीय आजीविका','काम सीखना'].map(x=>`<option ${state.opFilter===x?'selected':''}>${x}</option>`).join('')}</select><select id="careerFilter" aria-label="करियर के अनुसार फ़िल्टर">${careers.map(c=>`<option value="${c.id}" ${state.selectedCareer===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div>${state.mapList?`<div class="grid grid-2">${filtered.map(o=>opportunityCard(o,true)).join('')}</div>`:mapSvg()}<div class="notice" style="margin-top:13px">⚠️ पारदर्शिता: यह एक योजनात्मक नक्शा और नमूना डेटा है, वास्तविक नक्शा या लाइव अवसर नहीं। नाम, दूरी, रिक्ति, फीस और उपलब्धता की पुष्टि नहीं की गई है।</div></div>
${!state.mapList?opportunityCard(selected):''}${header('अन्य अवसर और सहायता','छात्रवृत्ति, सरकारी योजनाएँ और प्रशिक्षण — स्रोत देखकर आगे बढ़ें।')}<div class="grid grid-3">${[['🎓','छात्रवृत्ति','योग्यता और अंतिम तारीख आधिकारिक पोर्टल पर जाँचें।'],['🏛️','सरकारी योजनाएँ','योजना की शर्तें और आवेदन लिंक सत्यापित करें।'],['🧑‍🏫','मार्गदर्शक','शिक्षक या विश्वसनीय स्थानीय संस्था से सहायता लें।']].map(x=>`<div class="card"><div class="icon-box">${x[0]}</div><h3>${x[1]}</h3><p>${x[2]}</p><span class="tag tag-yellow">लाइव सूची जुड़ी नहीं</span></div>`).join('')}</div>`}
function renderTeacher(){const m=state.module;return `<section class="welcome"><div><div class="eyebrow">शिक्षक और समुदाय</div><h1>आपकी जानकारी,<br>बच्चों की नई सीख।</h1><p>अपने विद्यार्थियों की खूबियाँ देखें और अपनी भाषा में समझाए गए पाठ को छोटे सीखने के मॉड्यूल में बदलें।</p><button class="btn btn-primary" data-action="focus-module">🎙 बोलकर मॉड्यूल बनाओ</button></div><div class="hero-art" aria-hidden="true"><span>📚</span></div></section>
${header('शिक्षक डैशबोर्ड','डेमो विद्यार्थियों के साथ सीखने की प्रक्रिया दिखाएँ।')}<div class="grid grid-3"><div class="card"><div class="icon-box">👩‍🎓</div><div style="font-size:30px;font-weight:800">12</div><p>डेमो विद्यार्थी</p></div><div class="card"><div class="icon-box">✨</div><div style="font-size:30px;font-weight:800">4</div><p>नई स्किल्स खोजीं (डेमो)</p></div><div class="card"><div class="icon-box">📖</div><div style="font-size:30px;font-weight:800">${m?1:0}</div><p>आपके मॉड्यूल</p></div></div>
${header('विद्यार्थी और उनकी रुचियाँ','किसी विद्यार्थी को खोलकर उनकी ताकत और सुझाए गए रास्ते देखें।')}<div class="grid grid-3">${[{name:'आरव',desc:'डेयरी, दुकान और मोबाइल ठीक करने में मदद',id:'mobile',emoji:'🧑🏽‍🌾'},{name:'सिया',desc:'सिलाई और कपड़े के डिज़ाइन में रुचि',id:'tailor',emoji:'👩🏽‍🎨'},{name:'मोहन',desc:'खेती और नई तकनीक के बारे में जिज्ञासा',id:'agritech',emoji:'👨🏽‍🌾'}].map(s=>`<div class="card"><div class="row"><div class="career-emoji">${s.emoji}</div><div><h3>${s.name} <span class="tag">डेमो</span></h3><p>${s.desc}</p></div></div><button class="btn btn-outline btn-small" data-action="student-profile" data-id="${s.id}">प्रोफ़ाइल देखें</button> <button class="btn btn-soft btn-small" data-action="refer" data-id="${s.id}">सिफ़ारिश करें</button></div>`).join('')}</div>
${header('🎙 बोलकर मॉड्यूल बनाओ','अपनी भाषा में विषय समझाएँ। फिर शीर्षक, पाँच कदम और क्विज़ को जाँचकर प्रकाशित करें।')}<div class="grid grid-2"><div class="card" id="moduleBuilder"><div class="field"><label for="teacherInput">अपना पाठ बोलें या लिखें</label><textarea id="teacherInput">${esc(state.teacherInput)}</textarea></div><div class="row" style="flex-wrap:wrap"><button class="btn btn-primary" data-action="teacher-mic">🎙 बोलें</button><button class="btn btn-outline" data-action="generate-module">मॉड्यूल बनाएँ →</button><button class="btn btn-outline" data-action="speak-teacher">🔊 सुनें</button></div><p class="source">आवाज़ से लिखने की सुविधा समर्थित ब्राउज़र पर निर्भर है। टेक्स्ट विकल्प हमेशा उपलब्ध है।</p></div><div class="card"><h3>मॉड्यूल की सेटिंग</h3><p>बनाने के बाद आप शीर्षक, हर कदम, क्विज़ और कीमत बदल सकते हैं।</p><div class="field"><label>पाठ की कीमत</label><div class="tabs">${['Free','Per module','Subscription'].map(x=>`<button class="chip ${state.pricing===x?'active':''}" data-action="pricing" data-id="${x}">${x==='Free'?'मुफ़्त':x==='Per module'?'हर मॉड्यूल':'सब्सक्रिप्शन'}</button>`).join('')}</div></div>${state.pricing!=='Free'?`<div class="field"><label for="priceInput">डेमो कीमत (₹)</label><input id="priceInput" type="number" min="1" value="49"/></div>`:''}<div class="notice">भुगतान केवल डेमो है। कोई असली भुगतान या UPI लेन-देन नहीं होगा।</div></div></div>
${m?renderModule(m):`<div class="card empty">आपका मॉड्यूल यहाँ दिखेगा। ऊपर पाठ लिखें और “मॉड्यूल बनाएँ” दबाएँ।</div>`}`}
function renderModule(m){return `<div class="card" style="margin-top:16px"><div class="row between"><div><span class="tag">ड्राफ्ट मॉड्यूल</span><h2 style="margin:9px 0">${esc(m.title)}</h2></div><button class="btn btn-outline btn-small" data-action="preview-module">👁 पूर्वावलोकन</button></div><div class="field"><label for="moduleTitle">मॉड्यूल का शीर्षक</label><input id="moduleTitle" value="${esc(m.title)}"/></div><h3>सीखने के पाँच कदम</h3>${m.steps.map((s,i)=>`<div class="field"><label for="modstep${i}">कदम ${i+1}</label><textarea id="modstep${i}" rows="2">${esc(s)}</textarea></div>`).join('')}<h3>एक क्विज़ सवाल</h3><div class="field"><label for="quizQ">सवाल</label><input id="quizQ" value="${esc(m.quiz)}"/></div><div class="field"><label for="quizA">सही जवाब</label><input id="quizA" value="${esc(m.answer)}"/></div><div class="row" style="flex-wrap:wrap"><button class="btn btn-primary" data-action="save-module">डिवाइस में सेव करें</button><button class="btn btn-soft" data-action="publish-module">${m.published?'प्रकाशित ✓':'समीक्षा के बाद प्रकाशित करें'}</button><button class="btn btn-outline" data-action="speak-module">🔊 पाठ सुनें</button></div><p class="source">सेव की स्थिति: ${m.saved?'डिवाइस में सेव':'अभी सेव नहीं'} • कीमत: ${esc(state.pricing)} • ${m.published?'प्रकाशित':'ड्राफ्ट'}</p></div>`}
function makeModule(text){const topic=text.includes('पौध')?'पौधों की देखभाल':text.includes('पानी')?'पानी का सही उपयोग':text.includes('गणित')?'गणित की बुनियाद':text.includes('सफाई')?'साफ-सफाई की आदतें':'रोज़मर्रा के काम से सीखें';let steps;if(topic.includes('पौध'))steps=['बीज को पहचानें और देखें कि उसे उगने के लिए क्या चाहिए।','पौधे के लिए मिट्टी वाली साफ जगह या गमला तैयार करें।','मिट्टी की नमी देखकर उचित मात्रा में पानी दें।','पौधे को उसकी जरूरत के अनुसार धूप और हवा मिलने दें।','उपयुक्त खाद के बारे में जानें और पौधे की बढ़त नियमित देखें।'];else steps=['आज के विषय का उद्देश्य समझें और पहले से क्या जानते हैं, बताएं।','जरूरी चीज़ों और उनके सुरक्षित उपयोग की पहचान करें।','शिक्षक के उदाहरण को ध्यान से देखें और मुख्य बातें नोट करें।','शिक्षक की निगरानी में छोटा अभ्यास करें और सवाल पूछें।','सीखी बात को अपने शब्दों में दोहराएँ और रोज़मर्रा में उसका उपयोग सोचें।'];return {title:topic+' के पाँच कदम',steps,quiz:'पौधे की देखभाल करते समय हमें किस बात पर ध्यान देना चाहिए?',answer:'मिट्टी की नमी, धूप और पौधे की जरूरत',saved:false,published:false}}
function renderFamily(){const c=career(state.familyCareer);const o=opportunities.find(x=>x.career===c.id);const summary=state.familySummary||`1. चार कदम: ${c.steps.map(s=>s[0]).join(' → ')}।\n2. पास का मौका: ${o?o.name+' — केवल डेमो, वास्तविक अवसर सत्यापित नहीं।':'अभी सत्यापित नज़दीकी अवसर उपलब्ध नहीं।'}\n3. कितना खर्च: फीस और कुल खर्च की पुष्टि उपलब्ध नहीं है। प्रशिक्षण केंद्र से लिखित जानकारी लें।\n4. पहली कमाई: कमाई कौशल, अभ्यास, योग्यता, स्थानीय मांग और उपलब्ध काम पर निर्भर है। कोई आय या नौकरी की गारंटी नहीं।`;return `<section class="welcome"><div><div class="eyebrow">परिवार साथ चले</div><h1>बच्चे की रुचि समझें।<br>मिलकर रास्ता चुनें।</h1><p>सरल भाषा में जानें कि करियर तक पहुँचने के लिए क्या सीखना है, खर्च कैसे जाँचना है और पहला अवसर कैसे तलाशना है।</p><button class="btn btn-primary" data-action="speak-family">🔊 सुनकर समझें</button></div><div class="hero-art" aria-hidden="true"><span>👨‍👩‍👧</span></div></section>
${header('किस करियर पर बात करें?','विद्यार्थी की पसंद से रास्ता चुनें — परिवार साथ मिलकर चर्चा करे।')}<div class="field"><label for="familyCareer">करियर चुनें</label><select id="familyCareer">${careers.map(x=>`<option value="${x.id}" ${x.id===c.id?'selected':''}>${x.emoji} ${esc(x.name)}</option>`).join('')}</select></div>
<div class="card"><div class="row"><div class="career-emoji">${c.emoji}</div><div><span class="tag">परिवार के लिए सरल जानकारी</span><h2 style="margin:6px 0">${esc(c.name)}</h2><p style="margin:0">${esc(c.why)}</p></div></div><div class="divider"></div><div class="grid grid-2">${[['1','चार कदम','सीखें → अभ्यास करें → प्रशिक्षण/योग्यता जाँचें → अवसर तलाशें'],['2','पास का मौका',o?esc(o.name)+' (डेमो, सत्यापित नहीं)':'कोई सत्यापित स्थानीय अवसर उपलब्ध नहीं'],['3','कितना खर्च','सटीक फीस और कुल खर्च अज्ञात हैं। आधिकारिक स्रोत से पुष्टि करें।'],['4','पहली कमाई','कमाई कौशल, अभ्यास, योग्यता और स्थानीय मांग पर निर्भर है; गारंटी नहीं।']].map(x=>`<div class="card" style="background:#faf9f2;box-shadow:none"><div class="row"><div class="step-number">${x[0]}</div><h3>${x[1]}</h3></div><p style="margin-top:10px">${x[2]}</p></div>`).join('')}</div><div class="notice" style="margin-top:15px">यह सारांश सामान्य मार्गदर्शन है। पास के मौके के उदाहरण वास्तविक नहीं हैं। फीस, प्रशिक्षण और पात्रता की पुष्टि जरूरी है।</div><div class="field"><label for="familySummary">परिवार के साथ साझा करने के लिए सारांश</label><textarea id="familySummary" rows="8">${esc(summary)}</textarea></div><div class="row" style="flex-wrap:wrap"><button class="btn btn-primary" data-action="speak-family">🔊 सुनकर समझें</button><button class="btn btn-outline" data-action="share-family">WhatsApp पर साझा करें</button><button class="btn btn-soft" data-action="save-family">सारांश सेव करें</button></div></div>
${header('साथ मिलकर तय करें','विद्यार्थी की रुचि और पसंद सबसे अहम है।')}<div class="card"><div class="checkline"><input type="checkbox" id="familyDiscuss"/><label for="familyDiscuss">हमने इस रास्ते के बारे में साथ बैठकर बात की।</label></div><p>परिवार सवाल पूछ सकता है, जानकारी जुटाने में मदद कर सकता है और विकल्पों पर चर्चा कर सकता है। करियर का फैसला विद्यार्थी के साथ मिलकर करें।</p></div>`}
function showModal(html){$('#modalRoot').innerHTML=`<div class="modal-backdrop" data-action="backdrop"><section class="modal" role="dialog" aria-modal="true">${html}</section></div>`}function closeModal(){$('#modalRoot').innerHTML=''}
function onboarding(){showModal(`<h2>आपका परिचय</h2><p class="muted">बस उतनी जानकारी दें जितनी आपकी सीखने की राह बनाने में मदद करे।</p><div class="field"><label for="pname">आपको किस नाम से बुलाएँ?</label><input id="pname" value="${esc(state.profile.name||'')}" placeholder="आपका नाम (वैकल्पिक)"/></div><div class="field"><label for="plevel">आप अभी कहाँ पढ़ते हैं?</label><select id="plevel"><option>कक्षा 9–10</option><option>कक्षा 11–12</option><option>डिप्लोमा / ITI</option><option>स्नातक</option><option>स्नातक के बाद</option></select></div><div class="field"><label for="plocation">राज्य / जिला (वैकल्पिक)</label><input id="plocation" value="${esc(state.profile.location||'')}" placeholder="जैसे: उत्तर प्रदेश, गाज़ियाबाद"/></div><div class="field"><label for="pinterest">आपकी रुचियाँ</label><input id="pinterest" value="${esc(state.profile.interests||'')}" placeholder="जैसे: खेती, मोबाइल, डिज़ाइन"/></div><div class="checkline"><input id="pconsent" type="checkbox" ${state.consent?'checked':''}/><label for="pconsent">मैं समझता/समझती हूँ कि यह डेमो है और सुझाव संभावनाएँ हैं।</label></div><div class="modal-actions"><button class="btn btn-outline" data-action="close-modal">बाद में</button><button class="btn btn-primary" data-action="save-profile">सेव करें</button></div>`)}
function bind(){document.querySelectorAll('[data-action]').forEach(el=>el.addEventListener('click',()=>act(el.dataset.action,el.dataset.id,el)));document.querySelectorAll('[data-skill]').forEach(el=>el.addEventListener('change',()=>{state.skills[+el.dataset.skill].confirmed=el.checked;toast('आपकी स्किल की पुष्टि अपडेट हुई');persist()}));const t=$('#transcript');if(t)t.addEventListener('input',()=>state.transcript=t.value);const ti=$('#teacherInput');if(ti)ti.addEventListener('input',()=>state.teacherInput=ti.value);const of=$('#opFilter');if(of)of.addEventListener('change',()=>{state.opFilter=of.value;render()});const cf=$('#careerFilter');if(cf)cf.addEventListener('change',()=>{state.selectedCareer=cf.value;state.selectedOpportunity=(opportunities.find(o=>o.career===cf.value)||opportunities[0]).id;persist();render()});const fc=$('#familyCareer');if(fc)fc.addEventListener('change',()=>{state.familyCareer=fc.value;state.selectedCareer=fc.value;state.familySummary=null;persist();render()});const fs=$('#familySummary');if(fs)fs.addEventListener('input',()=>state.familySummary=fs.value)}
function act(a,id,el){if(a==='start-discovery'){document.querySelector('#transcript')?.focus();toast('अपनी रोज़ की ज़िंदगी के बारे में लिखें या बोलें।')}if(a==='onboard'||a==='profile')onboarding();if(a==='close-modal')closeModal();if(a==='save-profile'){state.profile={name:$('#pname').value.trim(),level:$('#plevel').value,location:$('#plocation').value.trim(),interests:$('#pinterest').value.trim()};state.consent=$('#pconsent').checked;persist();closeModal();render();toast('प्रोफ़ाइल इस डिवाइस पर सेव हुई।')}if(a==='analyze'){state.transcript=$('#transcript').value;const localSkills=skillExtract(state.transcript);fetch('/api/skills/extract',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text:state.transcript})}).then(r=>{if(!r.ok)throw new Error('API unavailable');return r.json()}).then(data=>{state.skills=data.skills.map(s=>({label:s.label,why:(localSkills.find(x=>x.label===s.label)||{}).why||'आपकी बात से निकला शुरुआती सुझाव।',confirmed:false}));if(!state.skills.length)state.skills=localSkills;finishAnalysis()}).catch(()=>{state.skills=localSkills;finishAnalysis()});toast('आपकी बात समझी जा रही है…')}if(a==='mic'||a==='teacher-mic'){const Speech=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Speech){toast('इस ब्राउज़र में बोलकर लिखने की सुविधा नहीं है। नीचे लिखकर जारी रखें।');return}try{const r=new Speech();r.lang=(localStorage.getItem('udaan_language')||'hi')==='en'?'en-IN':'hi-IN';r.interimResults=false;r.onstart=()=>{state.recording=true;render()};r.onresult=e=>{const text=e.results[0][0].transcript;if(a==='mic'){state.transcript=(state.transcript?state.transcript+' ':'')+text;render()}else{state.teacherInput=(state.teacherInput?state.teacherInput+' ':'')+text;render()}};r.onerror=e=>toast('आवाज़ नहीं मिली ('+e.error+')। लिखकर कोशिश करें।');r.onend=()=>{state.recording=false;render()};r.start()}catch(e){toast('माइक शुरू नहीं हो पाया। अनुमति जाँचें या लिखें।')}}if(a==='speak-transcript')speak(state.transcript||'अपना एक दिन बताइए।');if(a==='speak-teacher')speak(state.teacherInput);if(a==='open-career'){state.selectedCareer=id;state.familyCareer=id;persist();setTab('learn')}if(a==='choose-career'){state.selectedCareer=id;persist();render()}if(a==='save-career'){state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];persist();render();toast('आपकी पसंद अपडेट हुई।')}if(a==='toggle-step'){state.done=state.done.includes(id)?state.done.filter(x=>x!==id):[...state.done,id];persist();render();toast('सीखने की प्रगति डिवाइस पर सेव हुई।')}if(a==='next-step'){const c=career(state.selectedCareer);const n=c.steps.findIndex((_,i)=>!state.done.includes(c.id+'-'+i));if(n<0)toast('बहुत बढ़िया! आपने सभी कदम पूरे किए।');else{state.done.push(c.id+'-'+n);persist();render();toast('अगला कदम पूरा हुआ — डिवाइस पर सेव।')}}if(a==='show-list'){state.mapList=!state.mapList;render()}if(a==='select-op'){state.selectedOpportunity=id;render()}if(a==='save-op'){state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];persist();render();toast('मौके की जानकारी इस डिवाइस पर सेव हुई।')}if(a==='route-op')toast('यह डेमो स्थान है; वास्तविक रास्ते के लिए सत्यापित पता चाहिए।');if(a==='focus-module')$('#moduleBuilder')?.scrollIntoView({behavior:'smooth',block:'center'});if(a==='generate-module'){state.teacherInput=$('#teacherInput').value;state.module=makeModule(state.teacherInput);render();toast('मॉड्यूल ड्राफ्ट बना — कृपया सामग्री की समीक्षा करें।')}if(a==='pricing'){state.pricing=id;render()}if(a==='save-module'){if(!state.module)return;state.module.title=$('#moduleTitle').value;state.module.steps=state.module.steps.map((_,i)=>$('#modstep'+i).value);state.module.quiz=$('#quizQ').value;state.module.answer=$('#quizA').value;state.module.saved=true;localStorage.setItem('udaan_module',JSON.stringify(state.module));render();toast('मॉड्यूल इस डिवाइस पर सेव हुआ।')}if(a==='publish-module'){if(!state.module)return;state.module.title=$('#moduleTitle').value;state.module.steps=state.module.steps.map((_,i)=>$('#modstep'+i).value);state.module.quiz=$('#quizQ').value;state.module.answer=$('#quizA').value;state.module.saved=true;state.module.published=true;localStorage.setItem('udaan_module',JSON.stringify(state.module));render();toast('डेमो मॉड्यूल प्रकाशित स्थिति में है; कोई सर्वर पर साझा नहीं हुआ।')}if(a==='preview-module'){if(state.module)showModal(`<h2>${esc($('#moduleTitle')?.value||state.module.title)}</h2><p>सीखने के पाँच कदम</p><ol>${state.module.steps.map((s,i)=>`<li style="margin:10px 0">${esc($('#modstep'+i)?.value||s)}</li>`).join('')}</ol><strong>क्विज़:</strong><p>${esc($('#quizQ')?.value||state.module.quiz)}</p><strong>जवाब:</strong><p>${esc($('#quizA')?.value||state.module.answer)}</p><div class="modal-actions"><button class="btn btn-primary" data-action="close-modal">बंद करें</button></div>`)}if(a==='speak-module'&&state.module)speak(state.module.title+'. '+state.module.steps.join('. ')+'. सवाल: '+state.module.quiz);if(a==='student-profile'){const c=career(id);showModal(`<h2>डेमो विद्यार्थी की प्रोफ़ाइल</h2><span class="tag tag-yellow">सिंथेटिक नमूना</span><h3 style="margin-top:15px">${esc(c.name)}</h3><p>${esc(c.why)}</p><h3>सुझाया गया रास्ता</h3><p>${esc(c.learn)}</p><div class="notice">यह विद्यार्थी और प्रोफ़ाइल काल्पनिक डेमो डेटा हैं। वास्तविक विद्यार्थी डेटा नहीं है।</div><div class="modal-actions"><button class="btn btn-outline" data-action="close-modal">बंद करें</button><button class="btn btn-primary" data-action="teacher-recommend" data-id="${id}">रास्ता सुझाएँ</button></div>`)}if(a==='teacher-recommend'){state.selectedCareer=id;persist();closeModal();setTab('learn');toast('डेमो रास्ता चुना गया।')}if(a==='refer'){showModal(`<h2>विद्यार्थी को अवसर सुझाएँ</h2><p>यह डेमो रेफ़रल है। किसी वास्तविक संस्था को जानकारी नहीं भेजी जाएगी।</p><div class="field"><label for="refReason">सुझाव का कारण</label><textarea id="refReason">${esc(career(id).why)}</textarea></div><div class="checkline"><input id="refConsent" type="checkbox"/><label for="refConsent">विद्यार्थी/अभिभावक की उपयुक्त अनुमति की पुष्टि की गई है।</label></div><div class="modal-actions"><button class="btn btn-outline" data-action="close-modal">रद्द करें</button><button class="btn btn-primary" data-action="confirm-referral" data-id="${id}">डेमो रेफ़रल सेव करें</button></div>`)}if(a==='confirm-referral'){if(!$('#refConsent')?.checked){toast('पहले उपयुक्त अनुमति की पुष्टि करें।');return}closeModal();toast('डेमो रेफ़रल स्थानीय रूप से दर्ज हुआ।')}if(a==='speak-family')speak($('#familySummary')?.value||state.familySummary||familyDefault());if(a==='save-family'){state.familySummary=$('#familySummary').value;localStorage.setItem('udaan_family_summary',state.familySummary);toast('परिवार का सारांश इस डिवाइस पर सेव हुआ।')}if(a==='share-family'){const text=$('#familySummary').value;const url='https://wa.me/?text='+encodeURIComponent(text);if(navigator.share){navigator.share({text}).catch(()=>copyText(text))}else{window.open(url,'_blank','noopener,noreferrer');copyText(text);toast('WhatsApp खुल सकता है; संदेश भेजने से पहले आप समीक्षा करें।')}}if(a==='backdrop'&&el===event.target)closeModal()}
function finishAnalysis(){if(!state.skills.length)state.skills=[{label:'सीखने की जिज्ञासा',why:'आपकी बात में आगे समझने योग्य अनुभव और रुचियाँ हो सकती हैं। अपने काम के बारे में थोड़ा और बताइए।',confirmed:false}];render();toast('आपकी बात से शुरुआती स्किल्स तैयार हैं।')}
function familyDefault(){const c=career(state.familyCareer);return `चार कदम: ${c.steps.map(s=>s[0]).join(', ')}। पास का मौका: सत्यापित अवसर उपलब्ध नहीं; सूची में दिखने वाले मौके डेमो हैं। कितना खर्च: फीस की पुष्टि उपलब्ध नहीं। पहली कमाई: कौशल, प्रशिक्षण और स्थानीय मांग पर निर्भर; गारंटी नहीं।`}function copyText(text){if(navigator.clipboard?.writeText)navigator.clipboard.writeText(text).then(()=>toast('सारांश कॉपी हुआ।')).catch(()=>toast('सारांश चुनकर कॉपी करें।'));else toast('सारांश टेक्स्ट बॉक्स से कॉपी करें।')}
$('#languageToggle')?.addEventListener('click',()=>{localStorage.setItem('udaan_language',(localStorage.getItem('udaan_language')||'hi')==='hi'?'en':'hi');render();});document.querySelectorAll('.nav-item').forEach(b=>b.addEventListener('click',()=>setTab(b.dataset.tab)));$('#profileButton').addEventListener('click',onboarding);window.addEventListener('online',()=>{$('#connectionStatus').textContent='● कनेक्शन उपलब्ध';toast('इंटरनेट कनेक्शन उपलब्ध है।')});window.addEventListener('offline',()=>{$('#connectionStatus').textContent='● ऑफलाइन • डिवाइस पर सेव';toast('आप ऑफलाइन हैं। सेव की गई जानकारी उपलब्ध रहेगी।')});if(!navigator.onLine)$('#connectionStatus').textContent='● ऑफलाइन • डिवाइस पर सेव';try{const m=JSON.parse(localStorage.getItem('udaan_module'));if(m)state.module=m;const fs=localStorage.getItem('udaan_family_summary');if(fs)state.familySummary=fs}catch{}render();if('serviceWorker'in navigator&&location.protocol.startsWith('http'))window.addEventListener('load',()=>navigator.serviceWorker.register('/sw.js').catch(()=>{}));
